/* ============================================================
   НОРМАЛИЗАЦИЯ
   ============================================================ */

function norm(s){
  if(!s) return "";
  let out = "";
  const str = String(s);
  for(let i = 0; i < str.length; i++){
    let ch = str[i].toLowerCase();
    if(ch === "ё") ch = "е";
    else if(ch === "–" || ch === "—" || ch === "−" || ch === "‐" || ch === "‑") ch = "-";
    else if(ch === "\u00a0") ch = " ";
    else if(ch === "," || ch === ";" || ch === "(" || ch === ")" ||
            ch === "«" || ch === "»" || ch === "\"" || ch === "'" ||
            ch === "." || ch === "!" || ch === "?" || ch === ":" ||
            ch === "\n" || ch === "\t") ch = " ";
    out += ch;
  }
  return out.replace(/\s+/g, " ").trim();
}

/* нормализация с сохранением позиций символов (для подсветки) */
function normMapped(s){
  const src = String(s);
  let raw = "", map = [];
  for(let i = 0; i < src.length; i++){
    let ch = src[i].toLowerCase();
    if(ch === "ё") ch = "е";
    else if(ch === "–" || ch === "—" || ch === "−" || ch === "‐" || ch === "‑") ch = "-";
    else if(ch === "\u00a0") ch = " ";
    else if(ch === "," || ch === ";" || ch === "(" || ch === ")" ||
            ch === "«" || ch === "»" || ch === "\"" || ch === "'" ||
            ch === "." || ch === "!" || ch === "?" || ch === ":" ||
            ch === "\n" || ch === "\t") ch = " ";
    raw += ch;
    map.push(i);
  }
  let text = "", idx = [], prevSpace = true;
  for(let i = 0; i < raw.length; i++){
    const c = raw[i];
    if(c === " "){
      if(prevSpace) continue;
      prevSpace = true;
      text += " ";
      idx.push(map[i]);
    } else {
      prevSpace = false;
      text += c;
      idx.push(map[i]);
    }
  }
  if(text.endsWith(" ")){ text = text.slice(0, -1); idx.pop(); }
  return { text: text, map: idx };
}

/* извлечение годовых диапазонов из даты */
function parseRanges(dateN){
  const ranges = [];
  const re = /(\d{3,4})\s*-\s*(\d{3,4})/g;
  let m;
  while((m = re.exec(dateN)) !== null){
    const a = parseInt(m[1], 10), b = parseInt(m[2], 10);
    if(!isNaN(a) && !isNaN(b) && b >= a && b - a < 500) ranges.push([a, b]);
  }
  const single = /(\d{3,4})/g;
  while((m = single.exec(dateN)) !== null){
    const y = parseInt(m[1], 10);
    if(!isNaN(y)) ranges.push([y, y]);
  }
  return ranges;
}

function firstYear(dateN){
  const m = /(\d{3,4})/.exec(dateN);
  return m ? parseInt(m[1], 10) : 9999;
}

/* ============================================================
   ПОСТРОЕНИЕ ИНДЕКСА (один раз при загрузке)
   ============================================================ */

const searchIndex = historyData.map(function(e){
  const titleN = norm(e.title);
  const dateN = norm(e.date);
  const descN = norm(e.description);
  const kwN = (e.keywords || []).map(norm).filter(Boolean);
  const text = (titleN + " " + dateN + " " + descN + " " + kwN.join(" ")).replace(/\s+/g, " ").trim();
  return {
    src: e,
    titleN: titleN,
    dateN: dateN,
    descN: descN,
    kwN: kwN,
    text: text,
    ranges: parseRanges(dateN),
    year: firstYear(dateN)
  };
});

/* ============================================================
   ПОИСК
   ============================================================ */

function wordStarts(text, token){
  if(!text) return false;
  let pos = text.indexOf(token);
  while(pos !== -1){
    if(pos === 0) return true;
    const prev = text[pos - 1];
    if(prev === " ") return true;
    pos = text.indexOf(token, pos + 1);
  }
  return false;
}

function scoreRecord(rec, tokens){
  let total = 0;
  for(let i = 0; i < tokens.length; i++){
    const t = tokens[i];
    const isYear = /^\d{3,4}$/.test(t);
    let s = 0;

    if(rec.titleN === t) s = 120;
    else if(rec.titleN.startsWith(t)) s = 95;
    else if(wordStarts(rec.titleN, t)) s = 78;

    if(rec.dateN){
      if(rec.dateN === t || rec.dateN.startsWith(t)) { if(s < 105) s = 105; }
      else if(rec.dateN.includes(t)) { if(s < 68) s = 68; }
    }

    if(s < 72 && rec.kwN.length){
      let ks = 0;
      for(let k = 0; k < rec.kwN.length; k++){
        const kw = rec.kwN[k];
        if(kw === t){ ks = 72; break; }
        if(kw.startsWith(t)){ if(ks < 62) ks = 62; }
        else if(kw.includes(t)){ if(ks < 46) ks = 46; }
      }
      if(ks > s) s = ks;
    }

    if(isYear){
      const y = parseInt(t, 10);
      for(let r = 0; r < rec.ranges.length; r++){
        const range = rec.ranges[r];
        if(y >= range[0] && y <= range[1]){ if(s < 58) s = 58; break; }
      }
    }

    if(s < 32 && rec.descN.includes(t)) s = 32;
    if(s === 0 && rec.text.includes(t)) s = 12;
    if(s === 0) return 0;
    total += s;
  }
  return total;
}

function search(query){
  const nq = norm(query);
  if(!nq) return null;
  const tokens = nq.split(" ").filter(Boolean);
  if(!tokens.length) return null;

  const out = [];
  for(let i = 0; i < searchIndex.length; i++){
    const rec = searchIndex[i];
    const sc = scoreRecord(rec, tokens);
    if(sc > 0) out.push({ rec: rec, score: sc });
  }
  out.sort(function(a, b){
    if(b.score !== a.score) return b.score - a.score;
    return a.rec.year - b.rec.year;
  });
  return out;
}

/* ============================================================
   ПОДСВЕТКА СОВПАДЕНИЙ
   ============================================================ */

function escapeHtml(s){
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function highlight(text, tokens){
  if(!text) return "";
  const nm = normMapped(text);
  const ranges = [];
  for(let i = 0; i < tokens.length; i++){
    const t = tokens[i];
    if(!t) continue;
    let pos = nm.text.indexOf(t);
    while(pos !== -1){
      const start = nm.map[pos];
      const endIdx = pos + t.length - 1;
      const end = (nm.map[endIdx] !== undefined ? nm.map[endIdx] : text.length - 1) + 1;
      if(start < end) ranges.push([start, end]);
      pos = nm.text.indexOf(t, pos + t.length);
    }
  }
  if(!ranges.length) return escapeHtml(text);

  ranges.sort(function(a, b){ return a[0] - b[0]; });
  const merged = [ranges[0].slice()];
  for(let i = 1; i < ranges.length; i++){
    const last = merged[merged.length - 1];
    if(ranges[i][0] <= last[1]){
      if(ranges[i][1] > last[1]) last[1] = ranges[i][1];
    } else merged.push(ranges[i].slice());
  }

  let html = "", cursor = 0;
  for(let i = 0; i < merged.length; i++){
    const r = merged[i];
    if(r[0] > cursor) html += escapeHtml(text.slice(cursor, r[0]));
    html += "<mark>" + escapeHtml(text.slice(r[0], r[1])) + "</mark>";
    cursor = r[1];
  }
  if(cursor < text.length) html += escapeHtml(text.slice(cursor));
  return html;
}

/* ============================================================
   РЕНДЕР
   ============================================================ */

const input = document.getElementById("q");
const resultsEl = document.getElementById("results");
const emptyEl = document.getElementById("empty");
const countEl = document.getElementById("count");

const LIMIT = 60;

function render(results, tokens){
  if(!results){
    countEl.hidden = true;
    resultsEl.replaceChildren();
    emptyEl.style.display = "";
    return;
  }
  emptyEl.style.display = "none";

  const total = results.length;
  const shown = Math.min(total, LIMIT);

  countEl.hidden = false;
  countEl.textContent = total === 0
    ? "Ничего не найдено"
    : (total > shown ? "Найдено: " + total + " · показаны первые " + shown : "Найдено: " + total);

  const frag = document.createDocumentFragment();

  for(let i = 0; i < shown; i++){
    const rec = results[i].rec;
    const src = rec.src;

    const card = document.createElement("div");
    card.className = "card";

    const head = document.createElement("div");
    head.className = "head";

    if(src.date){
      const dateEl = document.createElement("span");
      dateEl.className = "date";
      dateEl.innerHTML = highlight(src.date, tokens);
      head.appendChild(dateEl);
    }

    const titleEl = document.createElement("span");
    titleEl.className = "title";
    titleEl.innerHTML = highlight(src.title, tokens);
    head.appendChild(titleEl);

    card.appendChild(head);

    if(src.description){
      const descEl = document.createElement("div");
      descEl.className = "desc";
      descEl.innerHTML = highlight(src.description, tokens);
      card.appendChild(descEl);
    }

    frag.appendChild(card);
  }

  resultsEl.replaceChildren(frag);
}

let lastQuery = "";
function update(){
  const q = input.value;
  if(q === lastQuery) return;
  lastQuery = q;
  const nq = norm(q);
  const tokens = nq ? nq.split(" ").filter(Boolean) : [];
  render(search(q), tokens);
}

input.addEventListener("input", update);

input.addEventListener("keydown", function(ev){
  if(ev.key === "Enter"){
    ev.preventDefault();
    input.blur();
  }
});

document.addEventListener("click", function(ev){
  if(!resultsEl.contains(ev.target)) input.focus();
});

window.addEventListener("pageshow", function(){ input.focus(); });

input.focus();
